before:
// The Aux header contains agent activity and native controls. Tab search lives
// in the sidebar footer.
combo_button_->SetVisible(false);
aux_pill_ = AddChildView(std::make_unique<AuxAgentPill>(browser_));
aux_agent_tabs_ = AddChildView(CreateAuxAgentTabsButton(browser_));

void VerticalTabStripTopContainer::SetAgentActive(bool active) {
  if (aux_pill_active_ == active) {
    return;
  }
  aux_pill_active_ = active;
  InvalidateLayout();
}

layout.child_layouts.emplace_back(aux_pill_.get(), false, gfx::Rect());
if (aux_agent_tabs_ && aux_agent_tabs_->GetVisible()) {
  const gfx::Size size = aux_agent_tabs_->GetPreferredSize();
  layout.child_layouts.emplace_back(aux_agent_tabs_.get(), true,
      gfx::Rect(std::max(0, (host_size.width() - size.width()) / 2),
                current_y, size.width(), size.height()));
  current_y += size.height();
}

if (aux_pill_) {
  const gfx::Size pref_size = aux_pill_->GetPreferredSize();
  gfx::Rect bounds(left_alignment,
                   std::max(0, y_baseline - pref_size.height() / 2),
                   pref_size.width(), pref_size.height());
  layout.child_layouts.emplace_back(aux_pill_.get(), aux_pill_active_, bounds);
}

if (aux_agent_tabs_ && aux_agent_tabs_->GetVisible()) {
  const gfx::Size size = aux_agent_tabs_->GetPreferredSize();
  const int activity_width = aux_pill_active_ && aux_pill_
      ? aux_pill_->GetPreferredSize().width() + 8 : 0;
  layout.child_layouts.emplace_back(aux_agent_tabs_.get(), true,
      gfx::Rect(left_alignment + activity_width,
                std::max(0, y_baseline - size.height() / 2),
                size.width(), size.height()));
}

if (aux_pill_ && aux_pill_->GetVisible() && IsHitInView(aux_pill_, point)) {
  return false;
}

raw_ptr<views::View> aux_pill_ = nullptr;
raw_ptr<views::View> aux_agent_tabs_ = nullptr;
bool aux_pill_active_ = false;
